import math

from hypothesis import strategies as st


def _isnum(x):
    return isinstance(x, float) and math.isfinite(x)


def precondition(*args):
    try:
        return (len(args) == 1 and isinstance(args[0], list)
                and len(args[0]) >= 2 and all(_isnum(x) for x in args[0]))
    except Exception:
        return False


def strategy():
    finite = st.floats(-1e9, 1e9, allow_nan=False, allow_infinity=False)
    edge = st.sampled_from([0.0, -1.0, 1.0, 1e9, -1e9, 0.5, -0.5, 1e-9])
    small_int = st.integers(-50, 50).map(float)
    base = st.one_of(edge, small_int, finite)
    return st.one_of(
        st.lists(base, min_size=2, max_size=8),
        base.flatmap(lambda x: st.lists(st.just(x), min_size=2, max_size=4)),
        st.lists(finite, min_size=2, max_size=8),
    ).map(lambda l: (l,))
